private static function resolve_segments( array $segments, $data, array $wildcard_values, string $current_path = '', bool $allow_missing_leaf = true ): array {
	if ( empty( $segments ) ) {
		return [
			[
				'path' => $current_path,
				'wildcard_values' => $wildcard_values,
			],
		];
	}

	if ( ! is_array( $data ) ) {
		return [];
	}

	$segment = array_shift( $segments );

	if ( $segment['is_wildcard'] ) {
		return self::resolve_wildcard_segment( $segments, $data, $segment, $wildcard_values, $current_path, $allow_missing_leaf );
	}

	return self::resolve_concrete_segment( $segments, $data, $segment, $wildcard_values, $current_path, $allow_missing_leaf );
}

private static function resolve_wildcard_segment( array $segments, array $data, array $segment, array $wildcard_values, string $current_path, bool $allow_missing_leaf ): array {
	$results = [];

	foreach ( array_keys( $data ) as $key ) {
		$new_wildcard_values = $wildcard_values;
		$new_wildcard_values[] = [
			'key' => $key,
			'type' => $segment['type'],
		];

		$new_path = self::append_to_path( $current_path, $key, $segment['type'] );

		$results = array_merge(
			$results,
			self::resolve_segments( $segments, $data[ $key ], $new_wildcard_values, $new_path, $allow_missing_leaf )
		);
	}

	return $results;
}

private static function resolve_concrete_segment( array $segments, array $data, array $segment, array $wildcard_values, string $current_path, bool $allow_missing_leaf ): array {
	$is_last_segment = empty( $segments );
	$key = $segment['value'];
	$key_exists = array_key_exists( $key, $data );

	if ( ! $key_exists && ! ( $allow_missing_leaf && $is_last_segment ) ) {
		return [];
	}

	$new_path = self::append_to_path( $current_path, $key, $segment['type'] );

	if ( $is_last_segment ) {
		return [
			[
				'path' => $new_path,
				'wildcard_values' => $wildcard_values,
			],
		];
	}

	return self::resolve_segments( $segments, $data[ $key ], $wildcard_values, $new_path, $allow_missing_leaf );
}

